    public static int[][] MergeIntervals(int[][] intervals)
    {
        if (intervals == null || intervals.Length == 0)
        {
            return new int[0][];
        }

        // Sort by start time using Array.Sort with a custom Comparison
        Array.Sort(intervals, delegate(int[] a, int[] b)
        {
            return a[0].CompareTo(b[0]);
        });

        List<int[]> merged = new List<int[]>();
        int[] currentInterval = intervals[0];
        merged.Add(currentInterval);

        for (int i = 1; i < intervals.Length; i++)
        {
            int[] nextInterval = intervals[i];

            // If intervals overlap or touch (end >= next start)
            if (currentInterval[1] >= nextInterval[0])
            {
                // Merge by updating the end of the current interval
                if (nextInterval[1] > currentInterval[1])
                {
                    currentInterval[1] = nextInterval[1];
                }
            }
            else
            {
                // No overlap, move to the next interval
                currentInterval = nextInterval;
                merged.Add(currentInterval);
            }
        }

        return merged.ToArray();
    }
