            char c = name[i];

            if (char.IsUpper(c))
            {
                // Add underscore if:
                // 1. Not at the start of the string
                // 2. Previous char was lowercase OR (Next char is lowercase and previous char was uppercase)
                // This handles: "userId" -> "user_id", "HTTPResponse" -> "http_response"
                if (i > 0)
                {
                    bool prevIsLower = char.IsLower(name[i - 1]);
                    bool nextIsLower = (i + 1 < name.Length) && char.IsLower(name[i + 1]);

                    if (prevIsLower || nextIsLower)
                    {
                        result.Append('_');
                    }
                }
                result.Append(char.ToLower(c));
            }
            else
