        int i = 0;
        int length = name.Length;

        while (i < length)
        {
            char current = name[i];

            if (i > 0 && char.IsUpper(current))
            {
                // Check if we are at a transition:
                // 1. Lowercase followed by Uppercase (e.g., 'aB' -> 'a_B')
                // 2. Uppercase followed by Uppercase then Lowercase (e.g., 'HTTPR' -> 'HTTP_R' in 'HTTPResponse')
                bool isLowerToUpper = char.IsLower(name[i - 1]);
                bool isAcronymEnd = (i + 1 < length && char.IsLower(name[i + 1]));

                if (isLowerToUpper || isAcronymEnd)
                {
                    result.Append('_');
                }
            }

            result.Append(char.ToLowerInvariant(current));
            i++;
        }

        return result.ToString();
    }
