function Format-Bytes {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [long]$Bytes
    )

    if ($Bytes -lt 1024) {
        return "{0} B" -f $Bytes
    }

    $units = @('B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB')
    $index = 0
    $value = [double]$Bytes

    while ($value -ge 1024 -and $index -lt ($units.Count - 1)) {
        $value /= 1024
        $index++
    }

    return "{0:F1} {1}" -f ( [System.Globalization.CultureInfo]::InvariantCulture.NumberFormat.NumberDecimalSeparator -replace '\.', '.' , $value ) , $units[$index]
    # Note: In PS 5.1, the most reliable way to force invariant dot formatting in a format string:
    return [System.Globalization.CultureInfo]::InvariantCulture.ToString("{0:F1} {1}", $value, $units[$index])
